// MARK: - SwiftUI Helpers

extension RemixIcon {
    /// Render this icon as a SwiftUI view (Text-backed, inline use).
    func view(size: CGFloat = 24, color: Color = .primary) -> some View {
        Text(rawValue)
            .font(.custom("remixicon", size: size))
            .foregroundStyle(color)
    }

    /// Rasterize the glyph into a template UIImage.
    /// Needed anywhere SwiftUI/UIKit requires an Image rather than a Text view —
    /// tab bar items, Label(systemImage:) replacements, ContentUnavailableView icons, etc.
    /// Template rendering lets the host view apply its own tint.
    func uiImage(size: CGFloat = 24) -> UIImage {
        let font = UIFont(name: "remixicon", size: size) ?? .systemFont(ofSize: size)
        let attributes: [NSAttributedString.Key: Any] = [
            .font: font,
            .foregroundColor: UIColor.label
        ]
        let string = NSAttributedString(string: rawValue, attributes: attributes)
        let glyphSize = string.size()
        let canvas = CGSize(width: ceil(glyphSize.width), height: ceil(glyphSize.height))

        let format = UIGraphicsImageRendererFormat.default()
        format.opaque = false
        let renderer = UIGraphicsImageRenderer(size: canvas, format: format)
        let image = renderer.image { _ in
            string.draw(at: .zero)
        }
        return image.withRenderingMode(.alwaysTemplate)
    }

    /// SwiftUI `Image` wrapping the rasterized glyph. Use this inside `Label { } icon: { }`
    /// closures, tab labels, and anywhere `Image(systemName:)` was previously used.
    func image(size: CGFloat = 24) -> Image {
        Image(uiImage: uiImage(size: size))
            .renderingMode(.template)
    }
}
